"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { CountUp } from "../lib/count-up";
import { Icon } from "../icons/icon";

export interface StatProps extends React.HTMLAttributes<HTMLDivElement> {
  label: React.ReactNode;
  value: React.ReactNode;
  icon?: React.ReactNode;
  /** Kleur van het icoonvlak. */
  tone?: "accent" | "green" | "amber" | "red" | "blue" | "violet";
  /** Verandering t.o.v. vorige periode, bv. +12.4. */
  delta?: number;
  /** Tekst achter de delta, bv. "vs. vorige maand". */
  deltaLabel?: React.ReactNode;
  /** Kleine grafiek onderaan (bv. <Sparkline/>). */
  chart?: React.ReactNode;
  /** Telt het getal in `value` op zodra de tegel in beeld komt. Standaard aan. */
  countUp?: boolean;
}

/** Stat — KPI-tegel met waarde, icoon en trend. */
export const Stat = React.forwardRef<HTMLDivElement, StatProps>(function Stat(
  { label, value, icon, tone = "accent", delta, deltaLabel, chart, countUp = true, className, ...rest },
  ref
) {
  const direction = delta === undefined ? null : delta >= 0 ? "up" : "down";

  return (
    <div ref={ref} className={cn("lui-stat", className)} {...rest}>
      <div className="lui-stat-top">
        <span className="lui-stat-label">{label}</span>
        {icon && <span className={cn("lui-stat-icon", `lui-stat-icon-${tone}`)}>{icon}</span>}
      </div>
      <div className="lui-stat-value">{countUp ? <CountUp value={value} /> : value}</div>
      {direction && (
        <div className={cn("lui-stat-delta", `lui-stat-delta-${direction}`)}>
          <Icon name={direction === "up" ? "arrowUp" : "arrowDown"} size={13} />
          {Math.abs(delta as number)}%
          {deltaLabel && <span className="lui-stat-delta-label">{deltaLabel}</span>}
        </div>
      )}
      {chart && <div className="lui-stat-chart">{chart}</div>}
    </div>
  );
});

/** Raster dat KPI-tegels netjes uitlijnt. */
export const StatGrid = React.forwardRef<
  HTMLDivElement,
  React.HTMLAttributes<HTMLDivElement> & { min?: number }
>(function StatGrid({ min = 200, className, style, ...rest }, ref) {
  return (
    <div
      ref={ref}
      className={cn("lui-stat-grid", className)}
      style={{ gridTemplateColumns: `repeat(auto-fit, minmax(${min}px, 1fr))`, ...style }}
      {...rest}
    />
  );
});

/* ============================ Stat (KPI) ============================ */
.lui-stat-grid { display: grid; gap: 16px; }

.lui-stat {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-lg); box-shadow: var(--sh-sm);
  padding: 18px 20px; display: flex; flex-direction: column; min-width: 0;
}
.lui-stat-top { display: flex; align-items: center; justify-content: space-between; gap: 12px; }
.lui-stat-label { font-size: 13px; color: var(--text-3); font-weight: 550; }
.lui-stat-icon {
  display: grid; place-items: center; width: 34px; height: 34px;
  border-radius: 9px; flex: none;
}
.lui-stat-icon svg { width: 17px; height: 17px; }
.lui-stat-icon-accent { background: var(--accent-tint); color: var(--accent); }
.lui-stat-icon-green { background: var(--green-tint); color: var(--green); }
.lui-stat-icon-amber { background: var(--amber-tint); color: var(--amber); }
.lui-stat-icon-red { background: var(--red-tint); color: var(--red); }
.lui-stat-icon-blue { background: var(--blue-tint); color: var(--blue); }
.lui-stat-icon-violet { background: var(--violet-tint); color: var(--violet); }

.lui-stat-value {
  font-size: 30px; font-weight: 700; letter-spacing: -0.03em;
  margin-top: 10px; line-height: 1; color: var(--text);
}
.lui-stat-delta {
  font-size: var(--fs-sm); font-weight: 600; margin-top: 7px;
  display: inline-flex; align-items: center; gap: 4px;
}
.lui-stat-delta-up { color: var(--green); }
.lui-stat-delta-down { color: var(--red); }
.lui-stat-delta-label { color: var(--text-3); font-weight: 500; margin-left: 3px; }
.lui-stat-chart { margin-top: 14px; }

"use client";
import * as React from "react";

/**
 * Laat een getal optellen van 0 (of de vorige waarde) naar `target` zodra het
 * element in beeld komt. Respecteert prefers-reduced-motion: dan staat de
 * eindwaarde er meteen.
 */
export function useCountUp(
  target: number,
  options: { duration?: number; ref?: React.RefObject<Element | null>; enabled?: boolean } = {}
): number {
  const { duration = 900, ref, enabled = true } = options;
  const [waarde, setWaarde] = React.useState(enabled ? 0 : target);
  const vorige = React.useRef(0);
  const [inBeeld, setInBeeld] = React.useState(!ref);

  React.useEffect(() => {
    if (!ref?.current || inBeeld) return;
    if (typeof IntersectionObserver === "undefined") {
      setInBeeld(true);
      return;
    }
    const observer = new IntersectionObserver(
      (entries) => {
        if (entries.some((entry) => entry.isIntersecting)) {
          setInBeeld(true);
          observer.disconnect();
        }
      },
      { threshold: 0.2 }
    );
    observer.observe(ref.current);
    return () => observer.disconnect();
  }, [ref, inBeeld]);

  React.useEffect(() => {
    if (!enabled || !inBeeld) return;
    const rustig =
      typeof window !== "undefined" && window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
    if (rustig || !Number.isFinite(target)) {
      vorige.current = target;
      setWaarde(target);
      return;
    }
    const van = vorige.current;
    const start = performance.now();
    let frame = 0;
    const stap = (nu: number) => {
      const t = Math.min(1, (nu - start) / duration);
      // easeOutExpo: snel vertrekken, zacht landen.
      const e = t === 1 ? 1 : 1 - Math.pow(2, -10 * t);
      setWaarde(van + (target - van) * e);
      if (t < 1) frame = requestAnimationFrame(stap);
      else vorige.current = target;
    };
    frame = requestAnimationFrame(stap);
    return () => {
      cancelAnimationFrame(frame);
      vorige.current = target;
    };
  }, [target, duration, enabled, inBeeld]);

  return enabled ? waarde : target;
}

interface Ontleed {
  voor: string;
  getal: number;
  na: string;
  decimalen: number;
  duizend: string;
  komma: string;
}

/** Haalt het eerste getal uit een tekst als "€ 12.480" of "98,4%" en onthoudt de opmaak. */
export function parseNumberText(tekst: string): Ontleed | null {
  const match = tekst.match(/\d+(?:[.,   ]\d+)*/);
  if (!match || match.index === undefined) return null;
  const ruw = match[0];
  const voor = tekst.slice(0, match.index);
  const na = tekst.slice(match.index + ruw.length);
  const minteken = /[-−]\s*$/.test(voor);

  const scheiders = ruw.match(/[.,   ]/g) ?? [];
  let komma = "";
  let duizend = "";
  if (scheiders.length > 0) {
    const laatste = scheiders[scheiders.length - 1] ?? "";
    const naLaatste = ruw.slice(ruw.lastIndexOf(laatste) + 1);
    const soorten = new Set(scheiders);
    if (soorten.size > 1) {
      komma = laatste;
      duizend = scheiders[0] ?? "";
    } else if (scheiders.length === 1 && naLaatste.length !== 3 && (laatste === "." || laatste === ",")) {
      komma = laatste;
    } else {
      duizend = laatste;
    }
  }
  const [heel, deel = ""] = komma ? [ruw.slice(0, ruw.lastIndexOf(komma)), ruw.slice(ruw.lastIndexOf(komma) + 1)] : [ruw, ""];
  const cijfers = heel.replace(/[^\d]/g, "");
  const getal = Number(`${cijfers}.${deel || "0"}`);
  if (!Number.isFinite(getal)) return null;
  return {
    voor: minteken ? voor.replace(/[-−]\s*$/, "") : voor,
    getal: minteken ? -getal : getal,
    na,
    decimalen: deel.length,
    duizend,
    komma: komma || ",",
  };
}

function schrijf(getal: number, o: Ontleed): string {
  const negatief = getal < 0;
  const [heel, deel] = Math.abs(getal).toFixed(o.decimalen).split(".");
  const metGroepen = o.duizend ? heel.replace(/\B(?=(\d{3})+(?!\d))/g, o.duizend) : heel;
  return `${o.voor}${negatief ? "−" : ""}${metGroepen}${deel ? o.komma + deel : ""}${o.na}`;
}

export interface CountUpProps {
  /** Getal of tekst met een getal erin; andere inhoud wordt gewoon getoond. */
  value: React.ReactNode;
  duration?: number;
  /** Zet op false om meteen de eindwaarde te tonen. */
  enabled?: boolean;
  className?: string;
}

/** CountUp — telt het getal in `value` op wanneer het in beeld komt, met behoud van opmaak. */
export function CountUp({ value, duration, enabled = true, className }: CountUpProps) {
  const ref = React.useRef<HTMLSpanElement>(null);
  const ontleed = React.useMemo(() => {
    if (typeof value === "number") {
      const tekst = String(value);
      const decimalen = tekst.includes(".") ? tekst.split(".")[1].length : 0;
      return { voor: "", getal: value, na: "", decimalen, duizend: "", komma: "." } satisfies Ontleed;
    }
    return typeof value === "string" ? parseNumberText(value) : null;
  }, [value]);

  const huidig = useCountUp(ontleed?.getal ?? 0, { duration, ref, enabled: enabled && ontleed !== null });

  if (!ontleed) return <>{value}</>;
  return (
    <span ref={ref} className={className} style={{ fontVariantNumeric: "tabular-nums" }}>
      {/* Screenreaders krijgen meteen de echte waarde. */}
      <span aria-hidden="true">{schrijf(huidig, ontleed)}</span>
      <span className="lui-sr-only">{typeof value === "number" ? String(value) : value}</span>
    </span>
  );
}
